using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ObsidianShacklesOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ObsidianShackles Omen Data")]
public class ObsidianShacklesOmenData : IncreasePurifyReceivedByEnemiesOmenData
{
	[Header("Obsidian Shackles")]
	[SerializeField]
	private int fewerPurifyAmount;

	private Func<int, GameObject, int> omenAdditionalPurifyAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAdditionalPurifyAction = (int purifyAmount, GameObject target) => (!ReferenceSingleton<BattleHandler>.Instance.IsTargetEnemy(target)) ? (purifyAmount - fewerPurifyAmount) : purifyAmount;
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnTargetModifierOmenActions.Add(omenAdditionalPurifyAction);
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnTargetModifierOmenActions.Remove(omenAdditionalPurifyAction);
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetIncreasePurifyReceivedByEnemiesLocalizedString() + "\n" + Smart.Format(base.OmenConvertedDescription(), fewerPurifyAmount);
	}
}
